#include <iostream>
using namespace std;

int u[102][102];

int main() {
    int n;
    cin >> n;

    int sum = 0;
    int a = (n - 1) / 2;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> u[i][j];

            if (i == j) {
                sum += u[i][j];
            }
            if (j == n - i - 1) {
                sum += u[i][j];
            }
            if (i == a) {
                sum += u[i][j];
            }
            if (j == a) {
                sum += u[i][j];
            }
        }
    }

    cout << sum - 3 * u[a][a];
    return 0;
}

